def read_level(text):
    level = int(text)
    if level < 0 or level > 9:
        raise ValueError("level out of range")
    return level

total = 0
while front() != "door":
    move()
    if here() == "terminal":
        info = scan()
        try:
            level = read_level(info["level"])
        except KeyError:
            say(info["pump"], "is silent")
        except ValueError:
            say(info["pump"], "is lying")
        else:
            say(info["pump"], "reads", level)
            total += level
unlock(total)
while not at_exit():
    move()

