from robot import *

class Drone:
    def __init__(self, name, battery=100):
        self.name = name
        self.battery = battery
        self.trips = 0
    def fly(self, distance):
        if distance <= 0:
            raise ValueError("distance must be positive")
        if distance > self.battery:
            raise ValueError("battery too low")
        self.battery -= distance
        self.trips += 1
        return self.battery

while here() != "terminal":
    move()
plan = scan()
scout = Drone("Scout", plan["battery"])
for trip in plan["trips"]:
    try:
        left = scout.fly(trip)
        say("Trip", trip, "done, battery", left)
    except ValueError as e:
        say("Refused:", e)
say("Trips:", scout.trips)
while front() != "door":
    move()
unlock(scout.battery)
while not at_exit():
    move()

