from robot import *

class OverloadError(Exception):
    pass

class Drone:
    kind = "Drone"
    def __init__(self, name):
        self.name = name
    def lift(self):
        raise NotImplementedError
    def describe(self):
        return f"{self.kind} {self.name} lifts {self.lift():.2f}"

class Lifter(Drone):
    kind = "Lifter"
    def __init__(self, name, arms):
        if arms > 4:
            raise OverloadError(f"{name} has too many arms")
        super().__init__(name)
        self.arms = arms
    def lift(self):
        return self.arms * 2.5

class Floater(Drone):
    kind = "Floater"
    def lift(self):
        return 1.25

while here() != "terminal":
    move()
total = 0
for name, arms in scan():
    try:
        if arms == 0:
            drone = Floater(name)
        else:
            drone = Lifter(name, arms)
    except OverloadError as e:
        say("Rejected:", e)
    else:
        say(drone.describe())
        total += drone.lift()
while front() != "door":
    move()
unlock(f"{total:.2f}")
while not at_exit():
    move()

