from robot import *

class Crate:
    def __init__(self, parts):
        self.parts = parts
    def __repr__(self):
        return f"Crate({self.parts})"
    def __str__(self):
        return f"crate of {len(self)} parts"
    def __len__(self):
        return len(self.parts)
    def __add__(self, other):
        return Crate(self.parts + other.parts)
    def __eq__(self, other):
        return self.parts == other.parts
    def __contains__(self, part):
        return part in self.parts

