from robot import *
import json

class Inventory:
    def __init__(self):
        self.items = {}
    def add(self, name, qty, price):
        item = self.items.setdefault(name, {"qty": 0, "price": price})
        item["qty"] += qty
        item["price"] = price
    def remove(self, name, qty):
        if name not in self.items or self.items[name]["qty"] < qty:
            raise ValueError(f"not enough {name}")
        self.items[name]["qty"] -= qty
    def total_value(self):
        return round(sum(i["qty"] * i["price"] for i in self.items.values()), 2)
    def low_stock(self, threshold=5):
        return sorted(n for n, i in self.items.items() if i["qty"] < threshold)
    def save(self, path):
        with open(path, "w") as f:
            json.dump(self.items, f, indent=2)
    @classmethod
    def load(cls, path):
        inv = cls()
        with open(path) as f:
            inv.items = json.load(f)
        return inv

inv = Inventory.load("warden/stock.json")
while here() != "terminal":
    move()
for name, qty, price in scan():
    inv.add(name, qty, price)
move()
while here() != "terminal":
    move()
for name, qty in scan():
    try:
        inv.remove(name, qty)
    except ValueError as e:
        say("Refused:", e)
inv.save("report.json")
say("Low stock:", ", ".join(inv.low_stock()))
while front() != "door":
    move()
unlock(inv.total_value())
while not at_exit():
    move()
